create table if not exists public.admins (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
alter table public.admins enable row level security;
drop policy if exists "admins: ver o proprio" on public.admins;
create policy "admins: ver o proprio" on public.admins for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete on public.admins from anon, authenticated;
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path = public as $$ select exists (select 1 from admins where user_id = auth.uid()) $$;
create table if not exists public.bans (user_id uuid primary key references auth.users(id) on delete cascade, until timestamptz, reason text not null default '', created_at timestamptz not null default now());
alter table public.bans enable row level security;
drop policy if exists "bans: ver" on public.bans;
create policy "bans: ver" on public.bans for select to authenticated using (user_id = auth.uid() or public.is_admin());
revoke insert, update, delete on public.bans from anon, authenticated;
create or replace function public.chk_ban() returns trigger language plpgsql security definer set search_path = public as $$ declare b record; begin select * into b from bans where user_id = new.author and (until is null or until > now()); if found then raise exception 'Você está banido %', case when b.until is null then 'permanentemente' else 'até ' || to_char(b.until at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI') end; end if; return new; end $$;
drop trigger if exists ban_posts on public.posts;
create trigger ban_posts before insert on public.posts for each row execute function public.chk_ban();
drop trigger if exists ban_comments on public.comments;
create trigger ban_comments before insert on public.comments for each row execute function public.chk_ban();
drop trigger if exists ban_chat on public.chat;
create trigger ban_chat before insert on public.chat for each row execute function public.chk_ban();
drop trigger if exists ban_messages on public.messages;
create trigger ban_messages before insert on public.messages for each row execute function public.chk_ban();
create or replace function public.admin_users(q text) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; return coalesce((select jsonb_agg(r) from (select p.id, p.name, p.level, p.gold, u.email, (select jsonb_build_object('until', b.until, 'reason', b.reason) from bans b where b.user_id = p.id and (b.until is null or b.until > now())) as ban from profiles p join auth.users u on u.id = p.id where p.name ilike '%' || coalesce(q, '') || '%' or u.email ilike '%' || coalesce(q, '') || '%' order by p.name limit 30) r), '[]'::jsonb); end $$;
create or replace function public.admin_set_gold(uid uuid, amount int) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; if amount is null or amount < 0 or amount > 1000000000 then raise exception 'valor inválido'; end if; update profiles set gold = amount where id = uid; if not found then raise exception 'jogador não encontrado'; end if; return jsonb_build_object('ok', true); end $$;
create or replace function public.admin_delete_post(pid uuid) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; delete from posts where id = pid; return jsonb_build_object('ok', true); end $$;
create or replace function public.admin_ban(uid uuid, minutes int, reason text) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; if exists (select 1 from admins where user_id = uid) then raise exception 'não é possível banir um administrador'; end if; insert into bans (user_id, until, reason) values (uid, case when minutes is null or minutes <= 0 then null else now() + make_interval(mins => minutes) end, coalesce(reason, '')) on conflict (user_id) do update set until = excluded.until, reason = excluded.reason, created_at = now(); return jsonb_build_object('ok', true); end $$;
create or replace function public.admin_unban(uid uuid) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; delete from bans where user_id = uid; return jsonb_build_object('ok', true); end $$;
